import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

layernorm_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void layernorm_kernel(
    const float* __restrict__ x,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ out,
    int N,
    float eps)
{
    int batch = blockIdx.x;
    const float* x_b = x + (long)batch * N;
    float* out_b = out + (long)batch * N;
    int tid = threadIdx.x;
    int block_threads = blockDim.x;
    int N4 = N / 4;
    int rem_start = N4 * 4;
    const float4* x_b4 = reinterpret_cast<const float4*>(x_b);
    float sum = 0.0f;
    float sqsum = 0.0f;
    for (int i = tid; i < N4; i += block_threads) {
        float4 v = x_b4[i];
        sum += v.x + v.y + v.z + v.w;
        sqsum += v.x * v.x + v.y * v.y + v.z * v.z + v.w * v.w;
    }
    for (int i = rem_start + tid; i < N; i += block_threads) {
        float v = x_b[i];
        sum += v;
        sqsum += v * v;
    }
    // warp-level reduction
    unsigned mask = 0xffffffffu;
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(mask, sum, offset);
        sqsum += __shfl_down_sync(mask, sqsum, offset);
    }
    __shared__ float warp_sum[32];
    __shared__ float warp_sqsum[32];
    int lane = tid & 31;
    int warp_id = tid >> 5;
    int num_warps = (block_threads + 31) >> 5;
    if (lane == 0) {
        warp_sum[warp_id] = sum;
        warp_sqsum[warp_id] = sqsum;
    }
    __syncthreads();
    __shared__ float mean;
    __shared__ float invstd;
    if (warp_id == 0) {
        float s = (lane < num_warps) ? warp_sum[lane] : 0.0f;
        float sq = (lane < num_warps) ? warp_sqsum[lane] : 0.0f;
        for (int offset = 16; offset > 0; offset >>= 1) {
            s += __shfl_down_sync(mask, s, offset);
            sq += __shfl_down_sync(mask, sq, offset);
        }
        if (lane == 0) {
            float m = s / N;
            float var = sq / N - m * m;
            if (var < 0.0f) var = 0.0f;
            mean = m;
            invstd = rsqrtf(var + eps);
        }
    }
    __syncthreads();
    float m = mean;
    float istd = invstd;
    const float4* gamma4 = reinterpret_cast<const float4*>(gamma);
    const float4* beta4 = reinterpret_cast<const float4*>(beta);
    float4* out_b4 = reinterpret_cast<float4*>(out_b);
    for (int i = tid; i < N4; i += block_threads) {
        float4 v = x_b4[i];
        float4 g = gamma4[i];
        float4 b = beta4[i];
        float4 r;
        r.x = (v.x - m) * istd * g.x + b.x;
        r.y = (v.y - m) * istd * g.y + b.y;
        r.z = (v.z - m) * istd * g.z + b.z;
        r.w = (v.w - m) * istd * g.w + b.w;
        out_b4[i] = r;
    }
    for (int i = rem_start + tid; i < N; i += block_threads) {
        float v = x_b[i];
        out_b[i] = (v - m) * istd * gamma[i] + beta[i];
    }
}

torch::Tensor layernorm_cuda(
    torch::Tensor x,
    torch::Tensor gamma,
    torch::Tensor beta,
    double eps)
{
    auto x_contig = x.contiguous();
    auto out = torch::empty_like(x_contig);

    int batch_size = x_contig.size(0);
    long N = x_contig.numel() / batch_size;

    const int threads = 256;
    const int blocks = batch_size;
    const int shared_mem = 2 * threads * sizeof(float);

    layernorm_kernel<<<blocks, threads, shared_mem>>>(
        x_contig.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        out.data_ptr<float>(),
        (int)N,
        (float)eps
    );

    return out;
}
"""

layernorm_cpp_source = r"""
torch::Tensor layernorm_cuda(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, double eps);
"""

layernorm_module = load_inline(
    name="layernorm_module",
    cpp_sources=layernorm_cpp_source,
    cuda_sources=layernorm_source,
    functions=["layernorm_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Model that performs Layer Normalization using a custom fused CUDA kernel.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.normalized_shape = normalized_shape
        self.weight = nn.Parameter(torch.ones(normalized_shape))
        self.bias = nn.Parameter(torch.zeros(normalized_shape))
        self.eps = 1e-5
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return layernorm_module.layernorm_cuda(x, self.weight, self.bias, self.eps)
batch_size = 16
features = 64
dim1 = 256
dim2 = 256
def get_inputs():
    x = torch.rand(batch_size, features, dim1, dim2)
    return [x]
def get_init_inputs():
    return [(features, dim1, dim2)]

